package com.oms.supplychain;
import com.oms.supplychain.service.wms.*;
import org.junit.jupiter.api.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.oms.supplychain.service.wms.WmsStore.*;
class QimenStockoutTest {
 QimenStockoutProtocol protocol=new QimenStockoutProtocol();
 Map<String,Object> connection(){return map("provider","QIMEN","api_version","2.0","app_key","APP","customer_id","CUSTOMER","endpoint","http://localhost/router");}
 Map<String,Object> payload(){return map("route",map("external_owner","OWNER","external_warehouse","WH"),"create_time","2026-10-25 12:00:00","receiver",map("name","供应商","mobile","13000000000","detailAddress","原供应商地址"),"lines",Collections.singletonList(map("id",1,"sku_sn","A","goods_name","商品A","inventory_type","CP","quantity",3,"batch_code","B1","purchase_price","2.50")));}
 Map<String,Object> doc(){return map("return_sn","CGT_TEST","supplier_sn","S","supplier_name","供应商","carrier_code","SF","reason","次品退仓","external_order","EXT1","cancel_reason","停止剩余退仓");}
 String body(String type,String qty){return "<request><deliveryOrder><deliveryOrderCode>CGT_TEST</deliveryOrderCode><deliveryOrderId>EXT1</deliveryOrderId><orderType>CGTH</orderType><ownerCode>OWNER</ownerCode><warehouseCode>WH</warehouseCode><outBizCode>M1</outBizCode><status>PARTDELIVERED</status><confirmType>1</confirmType><totalOrderLines>1</totalOrderLines><logisticsCode>SF</logisticsCode><expressCode>SF123</expressCode></deliveryOrder><orderLines><orderLine><orderLineNo>1</orderLineNo><itemCode>A</itemCode><ownerCode>OWNER</ownerCode><inventoryType>"+type+"</inventoryType><batchCode>B1</batchCode><actualQty>"+qty+"</actualQty></orderLine></orderLines></request>";}
 Map<String,String> signed(String body){Map<String,String> p=new TreeMap<>();p.put("app_key","APP");p.put("customerId","CUSTOMER");p.put("method","taobao.qimen.stockout.confirm");p.put("v","2.0");p.put("sign_method","md5");p.put("timestamp",java.time.LocalDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));p.put("sign",QimenProtocol.sign(p,body,"SECRET"));return p;}
 @Test void createUsesOfficialStockoutAndQualityFields(){WmsProtocol.Wire w=protocol.request(connection(),"SECRET","CREATE",doc(),payload());assertTrue(w.url.contains("taobao.qimen.stockout.create"));assertFalse(w.url.contains("deliveryorder.create"));assertTrue(w.body.contains("<orderType>CGTH</orderType>"));assertTrue(w.body.contains("<inventoryType>CC</inventoryType>"));assertTrue(w.body.contains("<batchCode>B1</batchCode>"));assertTrue(w.body.contains("<supplierCode>S</supplierCode>"));assertTrue(w.body.contains("<purchaseReturnPrice>2.50</purchaseReturnPrice>"));}
 @Test void queryUsesStockoutQueryIdentifiersAndCancelUsesCGTH(){WmsProtocol.Wire q=protocol.request(connection(),"SECRET","QUERY",doc(),payload());assertTrue(q.url.contains("stockout.query"));assertTrue(q.body.contains("<deliveryOrderCode>CGT_TEST</deliveryOrderCode>"));assertTrue(q.body.contains("<deliveryOrderId>EXT1</deliveryOrderId>"));WmsProtocol.Wire c=protocol.request(connection(),"SECRET","CANCEL",doc(),payload());assertTrue(c.url.contains("order.cancel"));assertTrue(c.body.contains("<orderType>CGTH</orderType>"));assertTrue(c.body.contains("<orderCode>CGT_TEST</orderCode>"));}
 @Test void signedPartialBadStockoutRetainsBatchAndHeaderWaybill(){String body=body("CC","2");Map<String,Object> r=protocol.callback(connection(),"SECRET",signed(body),body);assertEquals(false,r.get("complete"));assertEquals("SF123",r.get("waybill"));Map<String,Object> l=((List<Map<String,Object>>)r.get("lines")).get(0);assertEquals("CP",l.get("inventory_type"));assertEquals("B1",l.get("batch_code"));assertEquals(2L,l.get("quantity"));}
 @Test void badSignatureSalesMethodAndNegativeQuantityAreRejected(){String b=body("CC","2");Map<String,String> p=signed(b);p.put("sign","BAD");assertThrows(IllegalArgumentException.class,()->protocol.callback(connection(),"SECRET",p,b));Map<String,String> sales=signed(b);sales.put("method","taobao.qimen.deliveryorder.confirm");assertThrows(IllegalArgumentException.class,()->protocol.callback(connection(),"SECRET",sales,b));String negative=body("CC","-1");assertThrows(IllegalArgumentException.class,()->protocol.callback(connection(),"SECRET",signed(negative),negative));}
 @Test void wrongOrderTypeAndIncompleteFragmentsAreRejected(){String b=body("ZP","2").replace("CGTH","JYCK");assertThrows(IllegalArgumentException.class,()->protocol.callback(connection(),"SECRET",signed(b),b));String part=body("ZP","2").replace("<totalOrderLines>1","<totalOrderLines>2");assertThrows(IllegalArgumentException.class,()->protocol.callback(connection(),"SECRET",signed(part),part));}
 @Test void singleFinalConfirmationMayOmitConfirmTypeAndOutBizCode(){String finalBody=body("ZP","2").replace("PARTDELIVERED","DELIVERED").replace("<confirmType>1</confirmType>","").replace("<outBizCode>M1</outBizCode>","");Map<String,Object> r=protocol.callback(connection(),"SECRET",signed(finalBody),finalBody);assertEquals(true,r.get("complete"));assertEquals("FINAL",r.get("message_id"));}
 @Test void rejectedSupplierGoodsUseIndependentQTRKEntryOrder(){QimenReclaimProtocol p=new QimenReclaimProtocol();Map<String,Object>d=map("reclaim_sn","CGH_TEST","external_order","EXT","reason","供应商拒收收回","carrier_code","SF","waybill","BACK_WAYBILL");WmsProtocol.Wire w=p.request(connection(),"SECRET","CREATE",d,map("external_owner","OWNER","external_warehouse","WH"),Collections.singletonList(map("id",11,"sku_sn","A","goods_name","A","batch_code","B1","inventory_type","CP","quantity",2,"purchase_price","2.50")));assertTrue(w.url.contains("entryorder.create"));assertTrue(w.body.contains("<orderType>QTRK</orderType>"));assertTrue(w.body.contains("<inventoryType>CC</inventoryType>"));assertTrue(w.body.contains("<expressCode>BACK_WAYBILL</expressCode>"));assertTrue(p.request(connection(),"SECRET","CANCEL",d,map("external_owner","OWNER","external_warehouse","WH"),Collections.emptyList()).body.contains("<orderType>QTRK</orderType>"));}
 @Test void reclaimCallbackIsSignedAndPreservesActualGrade(){QimenReclaimProtocol p=new QimenReclaimProtocol();String b="<request><entryOrder><entryOrderCode>CGH_TEST</entryOrderCode><entryOrderId>EXT</entryOrderId><ownerCode>OWNER</ownerCode><warehouseCode>WH</warehouseCode><entryOrderType>QTRK</entryOrderType><outBizCode>RECEIVE1</outBizCode><confirmType>0</confirmType><status>FULFILLED</status><totalOrderLines>1</totalOrderLines></entryOrder><orderLines><orderLine><orderLineNo>11</orderLineNo><itemCode>A</itemCode><ownerCode>OWNER</ownerCode><batchCode>B1</batchCode><inventoryType>CC</inventoryType><actualQty>2</actualQty></orderLine></orderLines></request>";Map<String,String> params=signed(b);params.put("method","taobao.qimen.entryorder.confirm");params.put("sign",QimenProtocol.sign(params,b,"SECRET"));Map<String,Object> r=p.callback(connection(),"SECRET",params,b);assertEquals(true,r.get("complete"));assertEquals("CP",((List<Map<String,Object>>)r.get("lines")).get(0).get("inventory_type"));String changed=b.replace("QTRK","CGRK");params.put("sign",QimenProtocol.sign(params,changed,"SECRET"));assertThrows(IllegalArgumentException.class,()->p.callback(connection(),"SECRET",params,changed));}

 @Test void signedMessagePartRetainsDeclaredCountAndSnapshotVersion(){String b=body("ZP","2").replace("<totalOrderLines>1","<totalOrderLines>2").replace("</deliveryOrder>","<extendProps><omsSnapshotVersion>7</omsSnapshotVersion></extendProps></deliveryOrder>");Map<String,Object>r=protocol.part(connection(),"SECRET",signed(b),b);assertEquals(2L,r.get("total_lines"));assertEquals(1,r.get("source_lines"));assertEquals("7",r.get("snapshot_version"));}
 @Test void signedParcelMetadataKeepsItemsWithoutReplacingOutboundFacts(){String packs="<packages><package><packageCode>P1</packageCode><expressCode>SAME</expressCode><items><item><itemCode>A</itemCode><quantity>1</quantity><orderLineNo>1</orderLineNo><inventoryType>CC</inventoryType><batchCode>B1</batchCode></item></items></package><package><packageCode>P2</packageCode><expressCode>SAME</expressCode><items><item><itemCode>A</itemCode><quantity>1</quantity></item></items></package></packages>";String b=body("CC","2").replace("</request>",packs+"</request>");Map<String,Object>r=protocol.part(connection(),"SECRET",signed(b),b);List<Map<String,Object>>ps=(List<Map<String,Object>>)r.get("packages");assertEquals(2,ps.size());assertEquals("CP",((Map)((List)ps.get(0).get("items")).get(0)).get("inventory_type"));assertEquals(2L,((Map)((List)r.get("lines")).get(0)).get("quantity"));}
}
